"""Writes research/archivportal_d/candidates.json from the rows below (Archivportal-D sweep, 26 Oct 2026).

Every row was scored from the finding-aid description (seen: "catalogue"). Item ids are Archivportal-D / DDB ids;
the item page is https://www.archivportal-d.de/item/<id> (the same id works on deutsche-digitale-bibliothek.de).
"""
import json, os

HERE = os.path.dirname(os.path.abspath(__file__))
APD = 'https://www.archivportal-d.de/item/'
NOTE = 'Scored from the archive description during the Oct 2026 Archivportal-D sweep (research/archivportal_d/); not viewed'
CHK = 'checked 26 Oct 2026: known.py, quick web search'


def L(*pairs):
    return [{'label': lab, 'href': APD + i} for lab, i in pairs]


def row(year, date, title, corr, place, lang, region, period, shelf, folio, cls, status, why, imp, sol, dif,
        verify, links, prior, digit=False):
    return {'year': year, 'date': date, 'title': title, 'correspondents': corr, 'place': place, 'language': lang,
            'region': region, 'period': period, 'shelfmark': shelf, 'folio_note': folio, 'cls': cls,
            'status': status + (' Digitised: images in the Archivportal-D/DDB viewer.' if digit else ' Not digitised.'),
            'why': why, 'importance': imp, 'solvability': sol, 'difficulty': dif, 'score_note': NOTE, 'verify': verify,
            'links': links, 'seen': 'catalogue', 'source': 'Archivportal-D sweep', 'prior_art': prior}


